            "q": "What is a science? How does it work?",
            "ans": "Science is systematized knowledge derived through observation and experimentation. It works through the scientific method: recognizing problems, making observations, formulating hypotheses, testing deductions via controlled experiments, and drawing evidence-based conclusions."
