            "ans": "Two-Kingdom System (Linnaeus): Divided organisms into Plantae and Animalia. Advantage: Simple. Disadvantages: Grouped prokaryotes (bacteria) with plants; failed to place ambiguous organisms like Euglena; classified absorptive fungi with photosynthetic plants. Five-Kingdom System (Whittaker): Monera, Protista, Fungi, Plantae, Animalia. Advantages: Distinguishes prokaryotes from eukaryotes; separates fungi based on chitin and absorptive heterotrophy; accommodates transitional unicellular forms in Protista. Disadvantage: Cannot accommodate acellular viruses."
