        "sq": [
          {
            "q": "What was proposed by Schleiden and Schwann and what are the main points of cell theory?",
            "ans": "Matthias Schleiden (1838) and Theodor Schwann (1839) proposed the Cell Theory, later completed by Rudolf Virchow (1855). Main points: 1) All living organisms are composed of one or more cells. 2) The cell is the fundamental structural and functional unit of life. 3) All cells arise from pre-existing cells through division."
          },
          {
            "q": "Differentiate between simple and compound tissues.",
            "ans": "Simple Tissues: Made of a single type of cell performing uniform functions (e.g., Parenchyma, Collenchyma, Sclerenchyma). Compound (Complex) Tissues: Made of two or more different types of cells working together as a functional unit (e.g., Xylem and Phloem)."
          },
          {
            "q": "How does cell membrane help in maintaining equilibrium while exchanging materials with environment?",
            "ans": "The cell membrane is selectively permeable: it allows beneficial nutrients, gases, and water to diffuse inward down gradients, keeps cellular components from leaking out, and uses ATP-driven active transport pumps to maintain homeostatic solute concentrations."
          },
          {
            "q": "Differentiate between endocytosis and exocytosis.",
            "ans": "Endocytosis: Inward folding of the plasma membrane to engulf bulky extracellular substances into vesicles (Phagocytosis = solids; Pinocytosis = liquids). Exocytosis: Fusion of intracellular secretory vesicles with the plasma membrane to expel wastes or export hormones and enzymes."
          },
          {
            "q": "How does turgor pressure develop in a plant cell?",
            "ans": "When a plant cell absorbs water via osmosis in a hypotonic environment, its large central vacuole swells. The expanding vacuole pushes the protoplast against the rigid cellulose cell wall. This outward hydrostatic force is turgor pressure, keeping plants erect."
          }
        ],
