            "q": "List down major enzymes in the human digestive system. Elaborate their role in digestion.",
            "ans": "Major Digestive Enzymes: 1) Salivary Amylase (Ptyalin): In mouth, hydrolyzes starch to maltose at neutral pH. 2) Pepsin: In stomach, breaks proteins into polypeptides in acidic HCl medium (pH 2). 3) Pancreatic Amylase: In duodenum, digests remaining starch into maltose. 4) Trypsin (from pancreas): In duodenum, breaks polypeptides into smaller peptides. 5) Lipase (from pancreas): Hydrolyzes emulsified fats into fatty acids and glycerol. 6) Intestinal Peptidases and Disaccharidases: In ileum, convert peptides to amino acids and maltose/sucrose to glucose."
