            "q": "Discuss the function of major arteries and veins.",
            "ans": "Major Arteries (carry blood away from heart under high pressure): 1) Aorta: Largest systemic artery distributing oxygenated blood to all organs. 2) Pulmonary Artery: Only artery carrying deoxygenated blood from right ventricle to lungs. 3) Coronary Arteries: Supply oxygenated blood to cardiac muscle. 4) Renal & Carotid Arteries: Supply kidneys and brain. Major Veins (return low-pressure blood to heart): 1) Vena Cava (Superior & Inferior): Return deoxygenated blood from upper and lower body to right atrium. 2) Pulmonary Veins: Only veins carrying oxygenated blood from lungs to left atrium. 3) Hepatic Portal Vein: Transports nutrient-rich blood from gut to liver."
