            "q": "Describe the structure and pathway of the human air passageway from nostrils to alveoli with a neat diagrammatic description.",
            "ans": "The human air passageway consists of:\n1. Nostrils & Nasal Cavity: Filters dust using hairs, warms air through capillaries, and moistens it with mucus.\n2. Pharynx: A common muscular passage for both food and air.\n3. Larynx (Voice Box): Located above trachea; contains vocal cords and the glottis guarded by the epiglottis.\n4. Trachea (Windpipe): A 12 cm long tube supported by 16–20 C-shaped cartilaginous rings, lined with ciliated pseudostratified epithelium.\n5. Bronchi: The trachea bifurcates into right and left primary bronchi entering each lung.\n6. Bronchioles: Progressively narrower branches lacking cartilage, terminating in alveolar ducts.\n7. Alveoli: Microscopic thin-walled saccules surrounded by capillary plexuses where gas exchange occurs across a surface area of over 70 square meters."
