            "q": "Define osmoregulation and explain its significance to animal cells.",
            "ans": "Osmoregulation is the active regulation of the osmotic pressure of bodily fluids to maintain the balance of water and solute concentrations. In animal cells, which lack rigid cell walls, excess water uptake causes cells to lyse (burst), while excessive water loss causes cells to crenate (shrink) and die; osmoregulation ensures isotonic equilibrium."
