        "lq": [
          {
            "q": "Draw and describe the microscopic structure of a human nephron, explaining the functions of each region.",
            "ans": "A nephron consists of:\n1. Renal Corpuscle:\n- Glomerulus: Network of fenestrated capillaries receiving blood from the afferent arteriole; site of pressure filtration.\n- Bowman's Capsule: Double-layered cup with podocytes that collect the glomerular filtrate.\n2. Renal Tubule:\n- Proximal Convoluted Tubule (PCT): Highly coiled section lined with microvilli (brush border) that reabsorbs 100% of glucose and amino acids and 80% of water and NaCl.\n- Loop of Henle: U-shaped hairpin loop dipping into the medulla. The descending limb is permeable to water but impermeable to salts; the ascending limb actively pumps out NaCl and is impermeable to water, creating an osmotic gradient.\n- Distal Convoluted Tubule (DCT): Regulates electrolyte and acid-base balance under the influence of aldosterone and PTH.\n- Collecting Duct: Receives urine from multiple nephrons; reabsorbs water under ADH control before emptying into the renal pelvis."
          },
          {
            "q": "Explain in detail the three steps involved in the process of urine formation.",
            "ans": "1. Pressure Filtration (Ultrafiltration):\n- Blood enters the glomerulus via the wider afferent arteriole and exits through the narrower efferent arteriole, creating high hydrostatic pressure (approx. 55 mmHg).\n- This pressure forces water, glucose, amino acids, urea, and electrolytes through the capillary endothelial pores, basement membrane, and podocyte filtration slits into Bowman's space, forming glomerular filtrate.\n\n2. Selective Reabsorption:\n- As filtrate flows through the PCT, valuable solutes are reclaimed into peritubular capillaries: glucose and amino acids via active transport, Na+ via sodium-potassium pumps, Cl- and HCO3- passively, and water by osmosis.\n- In the Loop of Henle, countercurrent multiplication concentrates solutes in the medullary interstitium, allowing further water reabsorption.\n\n3. Tubular Secretion:\n- Epithelial cells of the DCT and collecting duct actively transport waste ions (H+, K+, NH4+) and foreign substances (penicillin, toxins) from capillary blood into the tubular lumen.\n- This step removes substances that escaped filtration and precisely maintains homeostatic blood pH."
          },
          {
            "q": "Describe the treatment options for chronic kidney failure: Hemodialysis, Peritoneal Dialysis, and Kidney Transplantation.",
            "ans": "1. Hemodialysis:\n- Blood from an artery (via an arteriovenous fistula) is pumped through a dialyzer containing thousands of semipermeable cellophane fibers.\n- Dialysate fluid flows countercurrent outside the fibers. Wastes (urea, excess K+) diffuse down their concentration gradient into the dialysate, while essential ions remain balanced.\n- Anticoagulated clean blood is returned to a vein. Performed 3 times a week, 4 hours per session.\n\n2. Peritoneal Dialysis:\n- The patient's abdominal peritoneal membrane serves as the natural dialyzing filter.\n- Dialysis fluid is infused into the peritoneal cavity via a surgically placed catheter.\n- Metabolic wastes diffuse from peritoneal capillary beds into the fluid over several hours.\n- The spent fluid is drained and replaced. Can be performed at home daily.\n\n3. Kidney Transplantation:\n- Definitive treatment involving surgical placement of a healthy donor kidney from a living relative or deceased donor.\n- The donor renal artery and vein are anastomosed to the recipient's external iliac vessels, and the ureter is connected to the bladder.\n- Requires strict HLA and ABO tissue matching and lifelong immunosuppressive therapy (e.g. cyclosporine) to prevent organ rejection."
          }
        ]
