            "q": "Compare asexual reproduction with sexual reproduction in terms of parents, cell division, and genetic variation.",
            "ans": "Asexual reproduction involves a single parent, relies exclusively on mitosis, produces genetically identical offspring (clones), and occurs rapidly. Sexual reproduction involves two parents, involves meiosis during gametogenesis and fertilization, produces genetically diverse offspring with novel gene combinations, and provides the raw material for adaptation and evolution."
