        "lq": [
          {
            "q": "Describe the basic steps of Genetic Engineering (Recombinant DNA Technology) with a detailed explanatory step-by-step account.",
            "ans": "Genetic engineering involves five crucial steps:\n1. Isolation of the Gene of Interest:\n- The target gene (e.g. human insulin gene) is located on the donor chromosome.\n- Restriction endonucleases ('molecular scissors') cut the DNA at specific palindromic sequences flanking the gene, leaving staggered single-stranded overhangs called 'sticky ends'.\n\n2. Selection and Cleavage of a Vector:\n- A cloning vector, typically a bacterial plasmid from E. coli, is isolated.\n- The plasmid is cut with the identical restriction endonuclease used for the donor DNA, generating complementary sticky ends.\n\n3. Construction of Recombinant DNA (Chimeric DNA):\n- The isolated gene of interest and linearized plasmid are mixed together.\n- Base-pairing occurs between their complementary sticky ends.\n- DNA Ligase ('molecular glue') forms covalent phosphodiester bonds between adjacent nucleotides, producing a stable circular Recombinant Plasmid.\n\n4. Transformation of Host Cells:\n- The recombinant plasmid is introduced into competent host bacterial cells (e.g. E. coli treated with ice-cold CaCl2 followed by a brief heat shock, or electroporation).\n- The bacteria take up the plasmid in a process called transformation.\n\n5. Growth, Selection, and Expression:\n- Transformed bacteria are plated on nutrient agar containing an antibiotic (e.g. ampicillin); only bacteria harboring the plasmid survive (marker selection).\n- Transformed colonies are transferred to large industrial fermenters where they multiply exponentially.\n- The foreign gene is transcribed into mRNA and translated into the desired protein (e.g. human insulin), which is harvested, purified, and formulated for therapeutic use."
          },
          {
            "q": "Explain the design, operational principles, and advantages of industrial fermenters (bioreactors).",
            "ans": "1. Design of a Fermenter:\n- A fermenter is a cylindrical stainless steel vessel designed to provide optimal, contamination-free conditions for mass microbial culture.\n- Agitator (Impeller): Motor-driven paddles that ensure uniform mixing of nutrients, microbes, and temperature throughout the broth.\n- Sparger: A perforated pipe at the bottom that injects pressurized sterile air or oxygen into the medium.\n- Cooling Jacket: Water jacket surrounding the vessel to absorb and remove metabolic heat generated by rapidly growing microbes, maintaining precise temperature (e.g. 37°C).\n- Sensors and Probes: pH probes, dissolved oxygen sensors, temperature sensors, and foam sensors linked to automated computerized feedback systems.\n- Acid/Base and Antifoam Inlets: Automatically inject corrective buffers or antifoam agents (silicone oils) to maintain homeostatic pH and prevent broth overflow.\n\n2. Operational Modes:\n- Batch Fermentation: Nutrients, water, and microorganisms are added at time zero. The culture proceeds through lag, log, and stationary phases without further addition of medium. Products (e.g. secondary metabolites like penicillin) are harvested when the process terminates, and the vessel is cleaned and sterilized.\n- Continuous Fermentation: Sterile fresh nutrient medium is pumped in continuously at a steady dilution rate while spent broth containing cells and products is harvested at the same rate, keeping the microbial population indefinitely in the exponential growth phase.\n\n3. Advantages of Fermenters:\n- Enables mass production of high-value biologicals (antibiotics, therapeutic proteins, industrial enzymes, amino acids).\n- Maximizes yield through computerized control of all growth variables.\n- Guarantees aseptic operation, preventing contamination by pathogenic or competing microorganisms."
          },
          {
            "q": "Discuss the major applications of biotechnology in the fields of Medicine and Agriculture.",
            "ans": "1. Applications in Medicine:\n- Therapeutic Proteins: Production of recombinant human insulin (Humulin) eliminating allergic reactions caused by bovine/porcine insulin; human growth hormone (somatotropin) to treat dwarfism; and erythropoietin to stimulate red blood cell production in anemia.\n- Vaccines: Recombinant DNA vaccines (e.g. Hepatitis B surface antigen vaccine) produced safely in yeast without using live attenuated pathogens.\n- Interferons: Antiviral glycoproteins produced by recombinant bacteria to treat viral infections and certain malignancies.\n- Gene Therapy: Direct replacement or supplementation of defective genes in human patients (e.g. treating Adenosine Deaminase deficiency SCID, cystic fibrosis, and sickle cell anemia).\n- Monoclonal Antibodies: Engineered for targeted cancer chemotherapy, delivering toxins exclusively to tumor cells.\n\n2. Applications in Agriculture:\n- Pest-Resistant Crops (Bt Crops): Cotton, corn, and potatoes engineered with the Cry toxin gene from Bacillus thuringiensis; insect larvae feeding on the crop die, reducing chemical pesticide use by over 70%.\n- Herbicide-Tolerant Crops: Roundup Ready soybeans and canola resistant to glyphosate; farmers can spray broad-spectrum herbicides to kill weeds without harming crops.\n- Nutritional Enhancement: Golden Rice engineered with phytoene synthase and carotene desaturase genes to produce beta-carotene (provitamin A) in the edible endosperm to combat childhood blindness.\n- Stress-Tolerant Crops: Engineered with drought, frost, and salinity-tolerant genes (e.g. osmoprotectant-synthesizing genes), allowing cultivation in marginal lands.\n- Delayed Fruit Ripening: Flavr Savr tomato with an antisense gene inhibiting polygalacturonase, preventing pectin breakdown and prolonging shelf-life."
          }
        ]
